    body;
    return typia.random<IPageIBbsUser.ISummary>();
  }

  /**
   * Get detailed profile/info for a specific user (Prisma: users table).
   *
   * This endpoint provides detailed profile data for a specific user from the
   * 'users' table as referenced in the Prisma schema. Path parameter 'id' is
   * the user's UUID.
   *
   * Authenticated users with moderator/admin privileges can view complete
   * detail (except password hash). Reveals username, email, bio, status,
   * roles, and join dates; optionally includes summary of posts, comments,
   * and votes via related endpoints.
   *
   * Security: Access restricted to moderators/administrators. Handles errors
   * for missing/not-found user IDs and permission control. May be used in
   * coordination with user editing, suspension, or review operations.
