files.packages/api/swagger.json:
{
  "openapi": "3.1.0",
  "paths": {
    "/bbs/users": {
      "patch": {
        "summary": "Retrieve a paginated/searchable list of users (Prisma: users table).",
        "description": "This endpoint retrieves a paginated, searchable list of users from the 'users' table.\n\nThe endpoint supports filtering by username, email, role, and account status. Only authorized moderators or administrators can access this endpoint for user management or review purposes. Results include summary info like username, email, role, status, and account creation date, but do not include sensitive data such as passwords.\n\nPagination and sorting are supported for efficient browsing. Relies on proper indexing and role-based access control to ensure performance and security. Errors include permission denied, database errors, and invalid search queries. This endpoint is usually accessed before taking moderator or admin actions on specific users.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUser.IRequest"
              }
            }
          },
          "description": "Filtering, search keywords, pagination, and sorting criteria for users listing.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IPageIBbsUser.ISummary"
                }
              }
            },
            "description": "List of users, metadata (pagination), summary user details (excluding sensitive fields)."
          }
        }
      },
      "post": {
        "summary": "Create/register a new user (Prisma: users table).",
        "description": "Creates a new user record based on the schema for 'users' in Prisma.\n\nIncludes username, password (hashed and stored securely), email, bio (optional), and role. When registering via public endpoints, signup is usually by the individual; admins may invite/create on behalf of others via this endpoint as well.\n\nValidation rules enforce uniqueness of username/email, password strength, and valid role assignment. Error responses for duplicate usernames/emails, or invalid role. Successful registration returns complete non-sensitive profile info. Password is accepted in cleartext but must never be returned or logged (only stored as hash).\n\nRelated: Might be accessed after registration for activating or managing new accounts.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUser.ICreate"
              }
            }
          },
          "description": "User profile, credentials, and initial role assignment for registration.",
          "required": true
        },
        "responses": {
          "201": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUser"
                }
              }
            },
            "description": "Confirmation and details of newly created user (excluding password hash)."
          }
        }
      }
    },
    "/bbs/users/{id}": {
      "get": {
        "summary": "Get detailed profile/info for a specific user (Prisma: users table).",
        "description": "This endpoint provides detailed profile data for a specific user from the 'users' table as referenced in the Prisma schema. Path parameter 'id' is the user's UUID.\n\nAuthenticated users with moderator/admin privileges can view complete detail (except password hash). Reveals username, email, bio, status, roles, and join dates; optionally includes summary of posts, comments, and votes via related endpoints.\n\nSecurity: Access restricted to moderators/administrators. Handles errors for missing/not-found user IDs and permission control. May be used in coordination with user editing, suspension, or review operations.\n\nValidation ensures 'id' is a valid user UUID. Returned data excludes password and sensitive internal tracking fields.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target user's UUID.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUser"
                }
              }
            },
            "description": "Detailed user information (profile, status, roles, join dates, etc)."
          }
        }
      },
      "put": {
        "summary": "Modify profile/credentials/status for a specific user (Prisma: users table).",
        "description": "Enables authorized updates to a user's record in 'users' table by UUID.\n\nRequest body includes changes to allow: username, email, biography, role, status, and password (if provided, must be re-hashed and stored securely). Edits restricted to permitted fields only. Only authorized moderators/admins can change roles and statuses; users may edit their own profiles via a different route.\n\nValidation ensures unique username/email (ignoring current user), valid role assignment, and password rules if reset. Handles errors for not found users, permission denied, and duplicate fields. Typically used in management consoles, not public-facing endpoints.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target user's UUID.",
            "required": true
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUser.IUpdate"
              }
            }
          },
          "description": "Editable user profile/role/status/credentials fields.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUser"
                }
              }
            },
            "description": "The updated user profile (excluding password hash)."
          }
        }
      },
      "delete": {
        "summary": "Soft-delete/deactivate user account by ID (Prisma: users table).",
        "description": "Handles account deletion or deactivation for users in the system by their UUID.\n\nImplements moderation and lifecycle rules: accounts are typically soft deleted (status changed or deletion timestamp set) instead of hard removal, preserving audit/history and relationships to posts.\n\nPermission restricted: Only moderators or administrators may use this endpoint. Validation ensures the ID exists and performs cascading or integrity checks. Returns confirmation and remaining user data (excluding sensitive detailed info). Cooperative with reporting and restoration workflows.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target user's UUID.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUser"
                }
              }
            },
            "description": "Confirmation of user soft delete/deactivation, summary response."
          }
        }
      }
    },
    "/bbs/userRoles": {
      "patch": {
        "summary": "List and search user roles (Prisma: user_roles table).",
        "description": "Fetches all roles available for assignment within the discussion board. Enables admin UIs to display, filter, and audit role definitions, including permission descriptions and assigned user counts.\n\nAccessible to admins only. Supports pagination, search, and sorting. Data returned allows for RBAC interface population and audit reporting.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUserRole.IRequest"
              }
            }
          },
          "description": "Filtering/searching/pagination info for user roles listing.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IPageIBbsUserRole.ISummary"
                }
              }
            },
            "description": "List of user roles (name, description, assigned user count, pagination info)."
          }
        }
      },
      "post": {
        "summary": "Create/register a new user role (Prisma: user_roles table).",
        "description": "Allows administrators to register a new role type for the discussion platform. Used for expanding the RBAC system, enabling fine-grained user permission control, or supporting policy revisions. Only accessible by admins.\n\nValidation: checks role name uniqueness and required description. Returns the new role's data and audit info.",
        "parameters": [],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUserRole.ICreate"
              }
            }
          },
          "description": "Role name, description, and audit details for registration.",
          "required": true
        },
        "responses": {
          "201": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUserRole"
                }
              }
            },
            "description": "Info for created user role (name, description, UUID, etc)."
          }
        }
      }
    },
    "/bbs/userRoles/{id}": {
      "get": {
        "summary": "Get details for a specific user role (Prisma: user_roles table).",
        "description": "Returns detailed information for the given user role (by UUID), including name, description, and associated users count. Intended for administration of RBAC and role assignments for users.\n\nRestricted to admin access. Used for audits, editing roles, or showing role details in admin UIs. Handles errors for not-found/invalid IDs and permission denied. May be associated with role modification endpoints.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target user role's UUID.",
            "required": true
          }
        ],
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUserRole"
                }
              }
            },
            "description": "Detailed user role info (name, description, assigned count, etc)."
          }
        }
      },
      "put": {
        "summary": "Update an existing user role (Prisma: user_roles table).",
        "description": "Permits role renaming or updating description for an existing role UUID. Usable by administrators only, primarily for adjusting policy or fixing incorrect details. Prevents changing to duplicate names, enforces update audit, and checks for valid ID.\n\nUpdates are reflected in downstream user assignment and authorization checks. Returns updated role details on success, errors otherwise.",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "schema": {
              "type": "string",
              "format": "uuid"
            },
            "description": "Target user role's UUID.",
            "required": true
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/IBbsUserRole.IUpdate"
              }
            }
          },
          "description": "Fields (name/description) to be updated for the user role.",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/IBbsUserRole"
                }
              }
            },
            "description": "Info of the updated user role."
          }
        }
      },
      "delete": {
        "summary": "Delete (deactivate/remove) user role by ID (Prisma: user_roles table).",
        "description": "Handles removing/deleting a user role record (by UUID) for the purpose of restructuring RBAC policy. If role is in use (users assigned), prevents deletion to maintain referential integrity.\n\nOnly administrators may access this endpoint. Checks for valid UUID, assignment count, and returns confirmation message plus remaining data. Priors checks required to avoid orphan users or dangling roles.",
